// Expected body:
// { bill_to_id, ship_to_id, ship_branch, price_branch, order_status,
//   ship_via, ship_date, required_date, po, release, internal_notes,
//   shipping_instructions, freight_in, writer, outside_sales, email,
//   lines: [{ productId, quantity, um?, umQuantity?, unitPrice?, comments?, ship_branch? }],
//   custom_lines: [{ line_number, name, ideal_sku, quantity, unit_price, est_cogs,
//                    variation_of: { product_id, description, serial_number } | null,
//                    customizations: [string], ship_branch? }] }
// ship_branch on a line (2026-10-19): the branch that line ships from. Lines
// on other branches than the header's go on their own generation, one per
// branch (Build order / Plan splits). Blank → the header's ship_branch.
// Custom lines (2026-10-19, on request) go to Eclipse as product 15680, the
// free-text "ITEM:" product, with their text in the line comment.
const CUSTOM_PRODUCT_ID = 15680;
const b = $input.first().json.body || {};
const branchOf = (v) => { const m = String(v == null ? '' : v).trim().match(/^(\d+)/); return m ? m[1] : ''; };
const headBranch = branchOf(b.ship_branch);
const regular = (Array.isArray(b.lines) ? b.lines : [])
  .map((l) => ({
    productId: Number(l.productId),
    quantity: Math.round(Number(l.quantity) || 0),
    um: l.um || 'ea',
    umQuantity: Number(l.umQuantity) || 1,
    unitPrice: l.unitPrice != null && l.unitPrice !== '' ? Number(l.unitPrice) : null,
    // Line comment, sent to Eclipse as lineItemProduct.comments.
    comments: String(l.comments == null ? '' : l.comments).trim(),
    branch: branchOf(l.ship_branch) || headBranch,
  }))
  .filter((l) => l.productId && l.quantity > 0);
// A custom line's comment: name, ideal SKU, the product it is a variation
// of, then one customization per line.
const customComment = (c) => {
  const out = [String(c.name || '').trim()];
  if (String(c.ideal_sku || '').trim()) out.push('SKU: ' + String(c.ideal_sku).trim());
  const v = c.variation_of;
  if (v && v.product_id) {
    out.push('Variation of ' + v.product_id + (v.description ? ' ' + String(v.description).trim() : '') +
      (v.serial_number ? ' SN ' + String(v.serial_number).trim() : ''));
  }
  for (const x of (Array.isArray(c.customizations) ? c.customizations : [])) if (String(x).trim()) out.push(String(x).trim());
  return out.filter(Boolean).join('\n');
};
const custom = (Array.isArray(b.custom_lines) ? b.custom_lines : [])
  .map((c) => ({
    productId: CUSTOM_PRODUCT_ID,
    quantity: Math.round(Number(c.quantity) || 0),
    um: 'ea',
    umQuantity: 1,
    unitPrice: isFinite(Number(c.unit_price)) && c.unit_price !== '' && c.unit_price != null ? Number(c.unit_price) : 0,
    comments: customComment(c),
    branch: branchOf(c.ship_branch) || headBranch,
    lineNumber: Math.round(Number(c.line_number) || 0),
  }))
  .filter((c) => c.quantity > 0 && c.comments);
// Page order: each custom line at its line_number (1-based among all sent
// lines), the regular lines filling the other places in their own order.
const total = regular.length + custom.length;
const slots = new Array(total).fill(null);
const late = [];
for (const c of custom) {
  const i = c.lineNumber - 1;
  if (i >= 0 && i < total && !slots[i]) slots[i] = c; else late.push(c);
}
let ri = 0;
for (let i = 0; i < total; i++) if (!slots[i]) slots[i] = ri < regular.length ? regular[ri++] : late.shift();
const lines = slots.filter(Boolean).map(({ lineNumber, ...l }) => l);
const fail = (msg) => [{ json: { ok: false, statusCode: 400, body: { success: false, error: msg, step: 'validate' } } }];
if (!b.bill_to_id) return fail('Missing bill_to_id');
if (!b.ship_to_id) return fail('Missing ship_to_id');
if (!b.writer) return fail('Missing writer (e_user_id)');
if (!lines.length) return fail('Add at least one line with a quantity.');
// Freight in, dollars; blank, invalid or negative → 0 (not sent).
const freight = Number(b.freight_in);
const isoDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? String(v) : '';
return [{ json: { ok: true, input: {
  billToId: String(b.bill_to_id), shipToId: String(b.ship_to_id),
  shipBranch: headBranch, priceBranch: String(b.price_branch || ''),
  orderStatus: String(b.order_status || 'Bid'), shipVia: String(b.ship_via || ''),
  shipDate: isoDate(b.ship_date), requiredDate: isoDate(b.required_date),
  po: String(b.po || ''), release: String(b.release || ''),
  internalNotes: String(b.internal_notes || ''), shippingInstructions: String(b.shipping_instructions || ''),
  writer: String(b.writer).toUpperCase(), outsideSales: String(b.outside_sales || ''),
  email: String(b.email || ''), lines,
  freightIn: isFinite(freight) && freight > 0 ? Math.round(freight * 100) / 100 : 0,
} } }];

// Field names follow the post_sorder() reference script. Rep-entered
// values win; customer defaults fill the gaps.
const inp = $('Validate').first().json.input;
const billEnv = $('Eclipse: get bill-to').first().json;
const shipEnv = $input.first().json;
const fail = (msg, step) => [{ json: { ok: false, statusCode: 502, body: { success: false, error: msg, step } } }];
if (billEnv.error) return fail('Eclipse bill-to lookup failed: ' + billEnv.error + ' ' + JSON.stringify(billEnv.message || ''), 'getBillTo');
if (shipEnv.error) return fail('Eclipse ship-to lookup failed: ' + shipEnv.error + ' ' + JSON.stringify(shipEnv.message || ''), 'getShipTo');
const bill = (Array.isArray(billEnv.results) ? billEnv.results[0] : billEnv) || {};
const ship = (Array.isArray(shipEnv.results) ? shipEnv.results[0] : shipEnv) || {};
if (!bill.id) return fail('Eclipse customer ' + inp.billToId + ' not found.', 'getBillTo');
if (!ship.id) return fail('Eclipse customer ' + inp.shipToId + ' not found.', 'getShipTo');
if (bill.isBillTo === false) return fail('Customer ' + bill.id + ' is not a Bill-To customer.', 'validate');
if (ship.isShipTo === false) return fail('Customer ' + ship.id + ' is not a Ship-To customer.', 'validate');

const val = (v) => (v && typeof v === 'object') ? (v.id || v.code || v.name || '') : (v == null ? '' : String(v));
// Defaults when the page sends blank dates: ship today, required 7 days
// out, pushed to Monday if that lands on a weekend.
const ymd = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const today = new Date();
const req = new Date(); req.setDate(req.getDate() + 7);
if (req.getDay() === 6) req.setDate(req.getDate() + 2);
else if (req.getDay() === 0) req.setDate(req.getDate() + 1);
const homeBranch = val(bill.homeBranch);
const headBranch = inp.shipBranch || homeBranch;

const lineItem = (l) => {
  const p = { productId: l.productId, quantity: l.quantity, um: l.um, umQuantity: l.umQuantity };
  if (l.unitPrice != null && isFinite(l.unitPrice)) p.unitPrice = l.unitPrice;
  // Line comment, with commentsId '1' as in the user's lineItemProduct
  // sample (UNVERIFIED what other ids mean; exports show commentTypeId '1').
  if (l.comments) { p.comments = l.comments; p.commentsId = '1'; }
  return { lineItemProduct: p };
};
// One generation per ship branch (2026-10-19): the order is created with
// the header branch's lines (or, when no line ships from it, the first
// line's branch); every other branch becomes its own generation after the
// create (Plan splits → Create Shipment → POST /LineItems).
const groups = [];
for (const l of inp.lines) {
  const br = l.branch || headBranch;
  let g = groups.find((x) => x.branch === br);
  if (!g) { g = { branch: br, lines: [] }; groups.push(g); }
  g.lines.push(l);
}
const first = groups.find((g) => g.branch === headBranch) || groups[0];
const extras = groups.filter((g) => g !== first).map((g) => ({ branch: g.branch, items: g.lines.map(lineItem) }));

const order = {
  priceBranch: inp.priceBranch || homeBranch,
  shipBranch: first.branch,
  billToCustomer: bill.id,
  shipToCustomer: ship.id,
  orderStatus: inp.orderStatus,
  salesSource: val(bill.salesSourceOverride) || 'Default Sales', // bill-to's, else 'Default Sales'
  shipDate: inp.shipDate || ymd(today),
  requiredDate: inp.requiredDate || ymd(req),
  customerPONumber: inp.po || val(bill.defaultPoNumber),
  customerReleaseNumber: inp.release,
  insideSalesPerson: '',
  outsideSalesPerson: inp.outsideSales || val(bill.outsideSalesperson) || 'WIHOUSE',
  writer: inp.writer,
  orderType: 'MOE',
  email: inp.email,
  street1: ship.addressLine1 || '',
  street2: ship.addressLine2 || '',
  city: ship.city || '',
  state: ship.state || '',
  postalCode: ship.postalCode || '',
  country: ship.countryCode || '',
  internalNotes: inp.internalNotes,
  shippingInstructions: inp.shippingInstructions,
  shipIds: [ship.id],
  lines: first.lines.map(lineItem),
};
// Ship via only when the rep picked one (a bid may leave it blank); no
// customer-default fallback, Eclipse decides what a missing shipVia means.
if (inp.shipVia) order.shipVia = inp.shipVia;
// Freight in from the page's totals box, as Eclipse's freightCharges (the
// only freight field in the post_sorder() reference body). UNVERIFIED that
// Eclipse books it as freight in (freightInBillable) and not freight out.
if (inp.freightIn > 0) order.freightCharges = inp.freightIn;
// Terms from the bill-to; left out when the bill-to has none.
if (val(bill.defaultTerms)) order.termsCode = val(bill.defaultTerms);
return [{ json: { ok: true, order, extras } }];

// Eclipse returns the created order wrapped as { results: [order] }, with
// id "S2737687" and generations[].generationId (verified 2026-10-17). The
// e_sorder_id is <id>.<first generation, 4-digit padded>, e.g. S2737687.0001.
const env = $input.first().json;
const r = Array.isArray(env.results) ? (env.results[0] || {}) : env;
const order = $('Build order').first().json.order;
if (env.error) {
  return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'createSalesOrder',
    error: 'Eclipse POST /SalesOrders failed: ' + env.error + ' ' + JSON.stringify(env.message || '').substring(0, 800), request: order } } }];
}
const rawId = String(r.id || r.eclipseOid || '');
const base = rawId.split('.')[0];
const gens = Array.isArray(r.generations) ? r.generations : [];
const genFromId = rawId.includes('.') ? rawId.split('.')[1] : '';
const gen = String(genFromId || (gens[0] && gens[0].generationId) || 1).padStart(4, '0');
if (!base) {
  return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'createSalesOrder',
    error: 'Eclipse created the order but returned no order id: ' + JSON.stringify(env).substring(0, 500) } } }];
}
return [{ json: { ok: true, orderId: base, e_sorder_id: base + '.' + gen, e_sorder_ids: [base + '.' + gen], eclipse: r } }];

// One more generation per extra ship branch (Build order's extras): a Create
// Shipment each, with the order's dates and status. The order itself was
// created with the first branch's lines.
const c = $('Check order').first().json;
const b = $('Build order').first().json;
const extras = b.extras || [];
if (!extras.length) return [{ json: { create: false } }];
return extras.map((g) => ({ json: {
  create: true, oid: c.orderId, shipBranch: g.branch,
  requiredDate: b.order.requiredDate, shipDate: b.order.shipDate, shipStatus: b.order.orderStatus,
} }));

// The generations Create Shipment made, one per extra ship branch, and the
// calls that fill them: their lines, plus ship via, shipping instructions
// and internal notes copied from the order (UNVERIFIED whether Create
// Shipment copies these itself; setting them again is harmless).
const c = $('Check order').first().json;
const b = $('Build order').first().json;
const o = b.order;
const pad = (g) => String(g).padStart(4, '0');
// The new generation's id from a Create Shipment answer. v1 read
// generationId at the top level; a { results: [order] } answer (the shape of
// SO Create) is handled too, taking the highest generation on that branch.
const shipmentGenId = (res, branch) => {
  if (!res || typeof res !== 'object') return '';
  const direct = res.generationId || res.generationID;
  if (direct) return String(Number(direct));
  const r0 = Array.isArray(res.results) ? res.results[0] : null;
  if (!r0) return '';
  if (r0.generationId) return String(Number(r0.generationId));
  const gens = (Array.isArray(r0.generations) ? r0.generations : [])
    .filter((g) => String(g.shipBranch) === String(branch) && String(g.status) !== 'Cancel');
  const ids = gens.map((g) => Number(g.generationId)).filter((n) => n > 0).sort((a, b) => b - a);
  return ids.length ? String(ids[0]) : '';
};
const shipments = $input.all();
const gens = [];
const empty = { posts: [], qty: [], prices: [], deletes: [], shipVia: [], shipDate: [], instructions: [], notes: [], status: [], cancels: [] };
for (let i = 0; i < b.extras.length; i++) {
  const g = b.extras[i];
  const res = shipments[i] ? shipments[i].json : null;
  const gid = res && !res.error ? shipmentGenId(res, g.branch) : '';
  if (!gid) {
    const why = !res ? 'no response' : res.error ? res.error + ' ' + JSON.stringify(res.message || '').substring(0, 500)
      : 'no generation id in ' + JSON.stringify(res).substring(0, 300);
    return [{ json: { ok: false, gens, step: 'createShipment',
      error: 'The lines for branch ' + b.extras.slice(i).map((x) => x.branch).join(', ') + ' could not be added: Eclipse Create Shipment failed (' + why + ').' } }];
  }
  gens.push({ branch: g.branch, generationId: gid, orderId: c.orderId + '.' + pad(gid), items: g.items });
}
const each = (value) => (value ? gens.map((g) => ({ orderId: g.orderId, value })) : []);
const ops = Object.assign({}, empty, {
  posts: gens.map((g) => ({ orderId: g.orderId, items: g.items })),
  shipVia: each(o.shipVia || ''),
  instructions: each(String(o.shippingInstructions || '').trim()),
  notes: each(String(o.internalNotes || '').trim()),
});
const has = {};
for (const k of Object.keys(ops)) has[k] = ops[k].length > 0;
return [{ json: { ok: true, gens, ops, has, changes: { generations: gens.map((g) => ({ e_sorder_id: g.orderId, ship_branch: g.branch, lines: g.items.length })) } } }];

// Every generation this placement made goes to update-hs-deal in one call.
// The order exists by now, so a failed split step is a warning in the answer
// (success stays true; the page reopens the order and shows it), never a 502
// that could make the rep place it again.
const c = $('Check order').first().json;
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
let warning = '';
for (const n of ['Resolve', 'Check posts', 'Check ship via', 'Check instructions', 'Check notes']) {
  if (!ran(n)) continue;
  const j = $(n).first().json;
  if (j && j.ok === false) { warning = j.error || (j.body && j.body.error) || 'A step after the create failed.'; break; }
}
const gens = ran('Resolve') ? ($('Resolve').first().json.gens || []) : [];
const ids = [c.e_sorder_id].concat(gens.map((g) => g.orderId));
return [{ json: { e_sorder_ids: ids, gens, warning } }];

const c = $('Check order').first().json;
const s = $('Sync list').first().json;
const b = $('Build order').first().json;
let r = $input.first().json || {};
// A non-JSON content type lands the body in `data` as text; parse it.
if (!r.orders && typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} }
// update-hs-deal answers { message, source, orders: [{ <hs_deal_id>: <e_sorder_id> }] }
// (verified 2026-10-17); pick the deal whose order id is the one just created
// (exact, or same order ignoring the gen suffix), else the only deal returned.
const pairs = [];
for (const o of (Array.isArray(r.orders) ? r.orders : [])) {
  for (const [dealId, soId] of Object.entries(o || {})) pairs.push([String(dealId), String(soId)]);
}
const base = (id) => String(id || '').split('.')[0].toUpperCase();
const hit = pairs.find((p) => p[1] === c.e_sorder_id) || pairs.find((p) => base(p[1]) === base(c.e_sorder_id)) || (pairs.length === 1 ? pairs[0] : null);
const hsDealId = hit ? hit[0] : '';
return [{ json: { statusCode: 200, body: {
  success: true,
  e_sorder_id: c.e_sorder_id,
  order_id: c.orderId,
  // Every generation placed (one per ship branch), first one first.
  e_sorder_ids: s.e_sorder_ids,
  generations: [{ e_sorder_id: c.e_sorder_id, ship_branch: b.order.shipBranch }]
    .concat((s.gens || []).map((g) => ({ e_sorder_id: g.orderId, ship_branch: g.branch }))),
  // Set when a generation for another ship branch could not be finished.
  warning: s.warning || '',
  hs_deal_id: hsDealId,
  // orders: what update-hs-deal returned, kept for troubleshooting a missing deal link.
  hubspot_sync: r.error ? { ok: false, error: String(r.error) } : { ok: true, orders: r.orders || null },
} } }];

const ops = $('Resolve').first().json.ops.posts;
const out = $input.all();
for (let i = 0; i < out.length; i++) {
  const r = out[i].json;
  if (r.error) {
    const error = 'Eclipse POST /LineItems failed on ' + ((ops[i] || {}).orderId || '?') + ': ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 500);
    return [{ json: { ok: false, statusCode: 502, error, body: { success: false, step: 'postLineItems', changes: $('Resolve').first().json.changes,
      error: error + '' } } }];
  }
}
return [{ json: { ok: true } }];

const ops = $('Resolve').first().json.ops.shipVia;
const out = $input.all();
for (let i = 0; i < out.length; i++) {
  const r = out[i].json;
  if (r.error) {
    const error = 'Eclipse PUT ship via failed on ' + ((ops[i] || {}).orderId || '?') + ': ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 500);
    return [{ json: { ok: false, statusCode: 502, error, body: { success: false, step: 'updateShipVia', changes: $('Resolve').first().json.changes,
      error: error + '' } } }];
  }
}
return [{ json: { ok: true } }];

const ops = $('Resolve').first().json.ops.instructions;
const out = $input.all();
for (let i = 0; i < out.length; i++) {
  const r = out[i].json;
  if (r.error) {
    const error = 'Eclipse PUT shipping instructions failed on ' + ((ops[i] || {}).orderId || '?') + ': ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 500);
    return [{ json: { ok: false, statusCode: 502, error, body: { success: false, step: 'updateShippingInstructions', changes: $('Resolve').first().json.changes,
      error: error + '' } } }];
  }
}
return [{ json: { ok: true } }];

const ops = $('Resolve').first().json.ops.notes;
const out = $input.all();
for (let i = 0; i < out.length; i++) {
  const r = out[i].json;
  if (r.error) {
    const error = 'Eclipse PUT internal notes failed on ' + ((ops[i] || {}).orderId || '?') + ': ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 500);
    return [{ json: { ok: false, statusCode: 502, error, body: { success: false, step: 'updateInternalNotes', changes: $('Resolve').first().json.changes,
      error: error + '' } } }];
  }
}
return [{ json: { ok: true } }];
